-- Applied live 2026-06-26 (audit_20260626_recover_ufc_setname_from_onchain_setdata);
-- repo-parity copy, record-only — never re-applied (prod already migrated).
-- UFC Strike: 72 editions had NULL set_name. Resolved the authoritative on-chain set name
-- via UFC_NFT (0x329feb3ab062d289) getSetMetadataByField(setId,"name") on a held moment per
-- edition (on-chain form "FIGHTER | EVENT | FINISH"), then derived event-style set_name by
-- stripping the fighter segment + normalizing "/"->" " and dropping commas. The convention
-- was VERIFIED to reproduce existing populated set_names EXACTLY on 11 known rows (UFC-num,
-- TUF, Fight Night). Event-style chosen for consistency (matches the 268-row plurality; a
-- set GROUPS editions so the fighter is excluded). Result: 72/72 filled, 0 null remaining,
-- check_public_security_invariants()=0, backup RLS-on/anon 0. old_set_name was NULL for all.
-- Revert: UPDATE editions e SET set_name = b.old_set_name FROM audit_20260626_ufc_setname_recovery b
--   WHERE e.id = b.edition_id;  (old_set_name is NULL for all 72 -> resets them to NULL.)

CREATE TABLE IF NOT EXISTS public.audit_20260626_ufc_setname_recovery (
  edition_id uuid PRIMARY KEY,
  external_id text, old_set_name text, new_set_name text, onchain_set_name text,
  backed_up_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.audit_20260626_ufc_setname_recovery ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.audit_20260626_ufc_setname_recovery FROM anon, authenticated;

