INSERT INTO public.audit_20260626_ufc_setname_recovery
  (edition_id, external_id, old_set_name, new_set_name, onchain_set_name)
SELECT e.id, e.external_id, e.set_name, d.new_set_name, d.onchain_set_name
FROM public.editions e JOIN derived d ON d.external_id = e.external_id
WHERE e.collection_id = '9b4824a8-736d-4a96-b450-8dcc0c46b023' AND e.set_name IS NULL
ON CONFLICT (edition_id) DO NOTHING;

UPDATE public.editions e SET set_name = b.new_set_name, updated_at = now()
FROM public.audit_20260626_ufc_setname_recovery b
WHERE e.id = b.edition_id AND e.set_name IS NULL;
